// === Tab: mySketch ===
i=l=0
s=100
draw=_=>{
  i||createCanvas(W=600, W, WEBGL)
	Z=stroke
	colorMode(HSB)
  background(0)
	scale(1.8)
  rotateY(i/3)
  for(z=-s; z<s; z+=5){
  	for(x=-s; x<s; x+=5){
      Z(abs(z*4)%360,W,W)
      if(noise(x/s,i,z/s)>.5){
        point(x,-s,z)
        point(x,s,z)
        Z(abs(z*4)%360,W,W,.1)
        line(x,-s,z,x,s,z)
        drawingContext.clear(256)
      }
    }
  }
  i+=.015
}
mousePressed=()=>{if (millis()-l>400){save('pix.jpg');l=millis();}}

